    private String extractTagValue(String qrData, String tag) {
        int index = qrData.indexOf(tag);
        if (index == -1)
            return null;
        int length = Integer.parseInt(qrData.substring(index + 2, index + 4));
        return qrData.substring(index + 4, index + 4 + length);
    }

