    /**
     * TC-004: Merchant city exceeding 15 characters is truncated to exactly 15 in Tag 60.
     * Precondition: A merchant must exist with a city longer than 15 characters.
     * The create merchant endpoint does not document an explicit "city" bound beyond what the
     * UpdateMerchantRequest shows (no documented maxLength), so we set it to exactly the 20-char
     * value the case uses and verify the QR's Tag 60 truncates to 15.
     */
    @Test
    public void merchantCityExceeding15CharactersIsTruncatedTo15InTag60() {
        long ts = System.currentTimeMillis();
        // Precondition: create a merchant with a 20-character city name.
        String merchantBody = """
                        {
                          "legalName": "TC004 Legal %d",
                          "tradeName": "TC004 Trade %d",
                          "registrationNo": "CR-TC004-%d",
                          "taxId": "TAX-TC004-%d",
                          "merchantCategoryCode": "5411",
                          "businessType": "CORPORATION",
                          "contactEmail": "tc004_%d@example.com",
                          "contactPhone": "+966501234001",
                          "city": "RiyadhCityNameExtra",
                          "country": "SA",
              "userId": %d
            }
            """.formatted(ts, ts, ts, ts, ts, System.currentTimeMillis() % 100_000);
        Response merchantResp = given().contentType(ContentType.JSON).body(merchantBody).when().post("/api/v1/merchants").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String merchantId = merchantResp.path("data.id") != null ? merchantResp.path("data.id") : merchantResp.path("id");
        Assert.assertNotNull(merchantId, "Precondition failed: create merchant returned no id. Body: " + merchantResp.asString());
        // The case's own assertion: generate a QR and inspect qrData.
        String qrBody = """
            {
              "merchantId": "%s",
              "qrType": "STATIC"
            }
            """.formatted(merchantId);
        Response qrResp = given().contentType(ContentType.JSON).body(qrBody).when().post("/api/v1/qr-codes").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String qrData = qrResp.path("data.qrData");
        Assert.assertNotNull(qrData, "qrData missing in response: " + qrResp.asString());
        // Tag 60 in EMV QR is encoded as "60" + length(2 digits) + value.
        // Find Tag 60 and extract its value; the truncated city should be the first 15 chars.
        // "RiyadhCityName" - 15 chars
        String expectedTruncated = "RiyadhCityNameE".substring(0, 15);
        Assert.assertTrue(qrData.contains(expectedTruncated), "Expected Tag 60 to contain truncated city '" + expectedTruncated + "'. qrData: " + qrData);
        // Verify it does NOT include the 16th character from the original city.
        Assert.assertFalse(qrData.contains("RiyadhCityNameEx"), "qrData should not contain the un-truncated city. qrData: " + qrData);
    }

