    // TC-006 - Null country code defaults to 'SA' in Tag 58
    @Test
    public void nullCountryCodeDefaultsToSAInTag58() {
        // Precondition: create a merchant with no country code specified (null/omitted)
        long ts = System.currentTimeMillis();
        String createMerchantBody = """
                        {
                          "legalName": "Null Country Merchant %d",
                          "tradeName": "NC Trade %d",
                          "registrationNo": "CR-NULL-%d",
                          "taxId": "TAX-NULL-%d",
                          "merchantCategoryCode": "5411",
                          "businessType": "CORPORATION",
                          "contactEmail": "nullcountry%d@example.com",
                          "contactPhone": "+966500000001",
                          "address": "123 Test Street",
                          "city": "Riyadh",
                          "state": "Riyadh Province",
                          "postalCode": "11564",
              "userId": %d
            }
            """.formatted(ts, ts, ts, ts, ts, System.currentTimeMillis() % 100_000);
        Response merchantResp = given().contentType(ContentType.JSON).body(createMerchantBody).when().post("/api/v1/merchants").then().statusCode(anyOf(is(200), is(201))).extract().response();
        merchantId = merchantResp.path("data.id");
        Assert.assertNotNull(merchantId, "Precondition failed: merchant create returned no id. Body: " + merchantResp.asString());
        // Verify the persisted merchant has no country code (per preconditions)
        String persistedCountry = merchantResp.path("data.country");
        Assert.assertTrue(persistedCountry == null || persistedCountry.isEmpty(), "Precondition failed: expected null/empty country, got: " + persistedCountry);
        // The actual assertion: POST /api/v1/qr-codes and observe qrData contains Tag 58 with 'SA'
        String qrBody = """
            {
              "merchantId": "%s",
              "qrType": "STATIC"
            }
            """.formatted(merchantId);
        Response qrResp = given().contentType(ContentType.JSON).body(qrBody).when().post("/api/v1/qr-codes").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String qrData = qrResp.path("data.qrData");
        Assert.assertNotNull(qrData, "qrData missing from response. Body: " + qrResp.asString());
        // EMV Tag 58 is "Country Code" (2 chars). In TLV, tag '58' (hex 3538) followed by length 02 and the 2-char value.
        // Look for Tag 58 (encoded in ASCII as "58") with length "02" and value "SA".
        Assert.assertTrue(qrData.contains("5802SA"), "Expected Tag 58 to contain 'SA' as default country code. qrData: " + qrData);
    }

