    private String createMerchant3(String legalName, String country) {
        long timestamp = System.currentTimeMillis();
        String body = """
                        {
                          "legalName": "%s",
                          "tradeName": "Trade_%d",
                          "registrationNo": "CR-%d",
                          "businessType": "CORPORATION",
                          "country": "%s",
              "userId": %d
            }
            """.formatted(legalName, timestamp, timestamp, country, System.currentTimeMillis() % 100_000);
        Response response = given().contentType(ContentType.JSON).body(body).when().post("/api/v1/merchants").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String id = response.path("data.id") != null ? response.path("data.id") : response.path("id");
        Assert.assertNotNull(id, "Precondition failed: Merchant creation failed to return ID");
        return id;
    }

