    // TC-015
    @Test
    public void multiByteUtf8MerchantNameExceeding25BytesIsTruncatedByByteCountInTag59() {
        String legalName = "商户名称测试商户名称测试商";
        String merchantId = createMerchant3(legalName, "SA");
        String qrRequestBody = """
            {
              "merchantId": "%s",
              "qrType": "STATIC"
            }
            """.formatted(merchantId);
        Response response = given().contentType(ContentType.JSON).body(qrRequestBody).when().post("/api/v1/qr-codes").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String qrData = response.path("data.qrData");
        Assert.assertNotNull(qrData, "qrData should not be null");
        Assert.assertTrue(qrData.contains("59"), "qrData should contain Tag 59");
        int tag59Index = qrData.indexOf("59");
        String lengthStr = qrData.substring(tag59Index + 2, tag59Index + 4);
        int byteLength = Integer.parseInt(lengthStr);
        Assert.assertTrue(byteLength <= 25, "Tag 59 length in bytes should be at most 25, but was: " + byteLength);
    }

